function setMode(m){mode=m;$('.paper').hidden=m!=='image';$('#text-view').hidden=m!=='text';for(const name of ['image','text']){const button=$('#'+name+'-tab');button.classList.toggle('selected',m===name);button.setAttribute('aria-selected',String(m===name))}$('.counts').innerHTML=originalCountMarkup();$('.legend').hidden=false;$('.paper-scroll').scrollTop=0;highlightCells();lines()}
